import{_ as a,o as n,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Erste Schritte","description":"","frontmatter":{},"headers":[],"relativePath":"de/getting-started.md","filePath":"de/getting-started.md"}'),s={name:"de/getting-started.md"};function i(d,e,l,o,c,p){return n(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="erste-schritte" tabindex="-1">Erste Schritte <a class="header-anchor" href="#erste-schritte" aria-label="Permalink to &quot;Erste Schritte&quot;">​</a></h1><p>Diese Seite führt dich vom Kauf bis zum ersten Öffnen des Einstellungspanels im Spiel. Sie gilt für jedes Nayretis Skript gleichermaßen.</p><h2 id="kaufen-und-herunterladen" tabindex="-1">Kaufen und herunterladen <a class="header-anchor" href="#kaufen-und-herunterladen" aria-label="Permalink to &quot;Kaufen und herunterladen&quot;">​</a></h2><ol><li>Kaufe das Skript im <a href="https://www.nayretis.com" target="_blank" rel="noreferrer">Nayretis Shop</a>. Die Bezahlung läuft über Tebex.</li><li>Melde dich im <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> mit dem Cfx.re Konto an, das du beim Kauf verwendet hast. Das Skript und <code>nay_lib</code> findest du unter deinen freigeschalteten Assets (Granted Assets).</li><li>Lade beide herunter. <code>nay_lib</code> gehört zu jedem Nayretis Skript und wird nie einzeln verkauft.</li></ol><p>Die Skripte sind durch Cfx Escrow geschützt: Sie starten nur auf einem Server, dessen Lizenzschlüssel zu dem Cfx.re Konto gehört, dem sie gehören.</p><h2 id="voraussetzungen" tabindex="-1">Voraussetzungen <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Voraussetzungen&quot;">​</a></h2><ul><li><a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>, gestartet und mit deiner Datenbank verbunden.</li><li>Eines der unterstützten Frameworks: ESX Legacy, QBCore, QBox oder ox_core. Inventare, Targets und Benachrichtigungen findest du unter <a href="/de/bridge/">Bridge</a>.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Kopiere den Ordner <code>nay_lib</code> und den Ordner des Skripts in deinen Ordner <code>resources</code>. Starte sie in der <code>server.cfg</code> nach deinen Framework-, Inventar- und Target-Ressourcen:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span># your framework, inventory and target resources here</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p><code>nay_lib</code> wird nur einmal installiert, egal wie viele Nayretis Skripte du nutzt. Lass es vor jedem Nayretis Skript starten.</p><h2 id="erster-start" tabindex="-1">Erster Start <a class="header-anchor" href="#erster-start" aria-label="Permalink to &quot;Erster Start&quot;">​</a></h2><p>Starte den Server. Die Datenbanktabellen werden automatisch angelegt, es gibt keine SQL-Datei zu importieren. In der Konsole solltest du Folgendes sehen:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[script:nay_lib] [INFO] Bridge ready: framework=qbox inventory=ox_inventory</span></span>
<span class="line"><span>[script:nay_lib] [INFO] Ready: settings, permissions and migrations loaded</span></span></code></pre></div><p>Die Namen von Framework und Inventar entsprechen dem, was auf deinem Server läuft.</p><h2 id="dir-selbst-zugriff-geben" tabindex="-1">Dir selbst Zugriff geben <a class="header-anchor" href="#dir-selbst-zugriff-geben" aria-label="Permalink to &quot;Dir selbst Zugriff geben&quot;">​</a></h2><p>Einstellungen werden im Spiel mit <code>/nay</code> bearbeitet. Gib der Admin-Gruppe in der <code>server.cfg</code> vollen Zugriff:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span></code></pre></div><p>Oder berechtige einen einzelnen Spieler über die Serverkonsole:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license &lt;license&gt; nay.admin</span></span></code></pre></div><p>Betritt dann den Server und gib <code>/nay</code> ein. Weitere Möglichkeiten findest du auf der Seite <a href="/de/nay-lib/permissions">Berechtigungen</a>.</p><h2 id="nachste-schritte" tabindex="-1">Nächste Schritte <a class="header-anchor" href="#nachste-schritte" aria-label="Permalink to &quot;Nächste Schritte&quot;">​</a></h2><ul><li>Lerne das <a href="/de/nay-lib/panel">/nay Panel</a> kennen: Sprachen, Design, Berechtigungen, API und Webhooks.</li><li>Richte <a href="/de/car-wash/">Car Wash</a> ein.</li><li>Etwas startet nicht? Lies die <a href="/de/faq">FAQ</a>.</li></ul>`,23)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
